<?php
$store=settings('store');$shipping=delivery_config();$all=lebanon_governorates();$rates=rows('SELECT * FROM governorate_rates');$byId=array_column($rates,null,'id');$first=$rates[0]??null;$initial=$first?json_decode($first['source_snapshot'],true):[];
?>
<p>Set one delivery fee for each governorate. Customers enter their city and detailed address themselves; city text never changes the fee. Amounts use <?= e($store['currency']) ?>. Unconfigured or inactive governorates cannot accept new orders.</p>
<?php if(!empty($initial['unmapped'])): ?><section class="panel migration-warning"><h2>Legacy governorate labels need review</h2><p>These old labels could not be mapped safely. No governorate was enabled automatically from them. Review the original rates below and explicitly confirm each new governorate’s coverage and fee.</p><ul><?php foreach($initial['unmapped'] as $old): ?><li><?= e($old['name'].' — '.$old['governorate'].' — '.$old['currency']) ?> <?= number_format($old['fee']/100,2) ?></li><?php endforeach ?></ul></section><?php endif ?>
<form class="panel cms-form" method="post" action="/admin/delivery"><?= csrf_field() ?><input type="hidden" name="section" value="delivery"><input type="hidden" name="action" value="settings"><h2>Delivery policy</h2><p>Every new checkout requires one of the eight governorates. Old city selection, Other area and flat-fee checkout controls are retired.</p><label class="check"><input type="checkbox" name="honor_free_threshold" value="1" <?= $shipping['honor_free_threshold']?'checked':'' ?>>Apply the Store settings free-delivery threshold: <?= (float)$store['free_delivery_threshold']>0?money(cents((string)$store['free_delivery_threshold'])):'currently disabled' ?>.</label><p class="muted">The threshold uses merchandise subtotal before discounts. Uncheck to always charge the configured governorate fee, unless a valid free-shipping promo code applies.</p><button class="button">Save delivery policy</button></form>
<div class="governorate-grid"><?php foreach($all as $id=>$g):$r=$byId[$id];$source=json_decode($r['source_snapshot'],true);$needsReview=in_array($r['origin'],['conflict','missing','unmapped'],true); ?>
<form class="panel cms-form governorate-rate" method="post" action="/admin/delivery" data-governorate-rate="<?= e($id) ?>"><?= csrf_field() ?><input type="hidden" name="section" value="delivery"><input type="hidden" name="action" value="save"><input type="hidden" name="governorate" value="<?= e($id) ?>"><h2><?= e($g['en']) ?> <small lang="ar" dir="rtl"><?= e($g['ar']) ?></small></h2><p class="<?= $r['active']&&$r['fee']!==null&&$r['currency']===$store['currency']?'muted':'error-text' ?>"><?= $r['fee']===null?'Fee not configured':($r['currency']!==$store['currency']?'Currency update required':($r['active']?'Available for delivery':'Delivery unavailable')) ?></p>
<?php if($needsReview): ?><div class="migration-warning"><p><strong><?= $r['origin']==='conflict'?'Conflicting legacy rates or rules':($r['origin']==='unmapped'?'Unmapped legacy coverage':'No safe existing governorate rate') ?></strong>. Delivery stays unavailable until you enter one governorate-wide fee and confirm coverage. No minimum, maximum or average fee has been selected automatically.</p><?php if(!empty($source['areas'])): ?><ul><?php foreach($source['areas'] as $old): ?><li><?= e($old['name']) ?>: <?= e($old['currency']) ?> <?= number_format($old['fee']/100,2) ?>; minimum <?= number_format($old['minimum_amount']/100,2) ?>; <?= $old['active']?'active':'inactive' ?></li><?php endforeach ?></ul><?php endif ?><label class="check"><input type="checkbox" name="confirm_resolution" value="1" required>I reviewed the old rates and confirm this governorate’s fee, rules and coverage.</label></div><?php elseif($r['origin']==='legacy_flat'): ?><p class="muted">Copied from the previously active Store flat delivery fee. Inactive city rates were retained for reference.</p><?php elseif($r['origin']==='uniform_areas'): ?><p class="muted">Copied from matching old area fees, minimums and availability. This fee now covers the whole governorate.</p><?php endif ?>
<label>Delivery fee for <?= e($g['en']) ?> (<?= e($store['currency']) ?>)<input type="number" name="fee" min="0" step="0.01" inputmode="decimal" value="<?= $r['fee']===null?'':number_format($r['fee']/100,2,'.','') ?>" placeholder="Not configured"></label><label class="check"><input type="checkbox" name="active" value="1" <?= $r['active']?'checked':'' ?>>Available for delivery</label><p class="muted">Zero explicitly means free delivery. Leave blank only while unavailable.</p>
<?php if($r['currency']!==$store['currency']): ?><p class="error-text">Previous amounts used <?= e($r['currency']) ?>. Re-enter the fee and minimum in <?= e($store['currency']) ?>.</p><label class="check"><input type="checkbox" name="confirm_currency" required value="1">I confirm the new currency and amounts.</label><?php endif ?>
<details><summary>Additional rules and migration history</summary><label>Minimum merchandise subtotal (0 = none)<input type="number" name="minimum_amount" min="0" step="0.01" required value="<?= number_format($r['minimum_amount']/100,2,'.','') ?>"></label><label>Estimated delivery time<input name="estimate" maxlength="160" value="<?= e($r['estimate']) ?>"></label><label>Customer-facing delivery notes<textarea name="notes" maxlength="1500" rows="2"><?= e($r['notes']) ?></textarea></label><p class="muted">Minimums use merchandise subtotal before discounts. Existing order fees and addresses never change.</p><?php if(!empty($source['areas'])): ?><p>Original city rates (read-only migration record):</p><ul><?php foreach($source['areas'] as $old): ?><li><?= e($old['name'].' — '.$old['currency']) ?> <?= number_format($old['fee']/100,2) ?>; minimum <?= number_format($old['minimum_amount']/100,2) ?>; <?= $old['active']?'active':'inactive' ?></li><?php endforeach ?></ul><?php endif ?></details><button class="button">Save <?= e($g['en']) ?> rate</button></form>
<?php endforeach ?></div>
<section class="panel"><h2>Preview a governorate fee</h2><form class="form-grid" method="get" action="/admin/delivery"><label>Governorate<select name="preview_governorate" required><option value="">Choose governorate</option><?php foreach($all as $id=>$g): ?><option value="<?= e($id) ?>" <?= ($_GET['preview_governorate']??'')===$id?'selected':'' ?>><?= e($g['en']) ?></option><?php endforeach ?></select></label><label>Merchandise subtotal before discounts (<?= e($store['currency']) ?>)<input name="preview_subtotal" type="number" min="0" step="0.01" required value="<?= e(text_input($_GET,'preview_subtotal',20)) ?>"></label><button class="button">Preview delivery fee</button></form><?php if(!empty($_GET['preview_governorate'])):$preview=governorate_price(cents(text_input($_GET,'preview_subtotal',20,true)),false,governorate_id(text_input($_GET,'preview_governorate',32,true))); ?><p role="status"><?= $preview['status']==='ready'?e($preview['governorate']).': '.($preview['fee']?money($preview['fee']):'Free Delivery'):e($preview['message']) ?></p><?php endif ?></section>
